"use client";

import React from "react";
import { AlertCircle, ArrowRight } from "lucide-react";

export function BillingPlanLimitAlert() {
  return (
    <div className="w-full max-w-sm bg-card/45 backdrop-blur-xl border border-amber-500/20 p-5 rounded-2xl shadow-xl select-none font-sans text-foreground">
      <div className="flex items-center gap-1.5 mb-3">
        <AlertCircle className="w-4 h-4 text-amber-400" />
        <span className="text-xs font-bold uppercase tracking-wider text-amber-400">Plan Quota Warning</span>
      </div>

      <p className="text-xs text-muted-foreground/80 leading-normal mb-4">
        You are currently using 92% of your monthly registered server seats. Upgrade today to avoid service disruptions.
      </p>

      <button className="w-full py-2 bg-amber-600 hover:bg-amber-500 text-white font-bold text-xs rounded-xl flex items-center justify-center gap-1 transition-all">
        <span>Upgrade Subscription Plan</span>
        <ArrowRight className="w-3.5 h-3.5" />
      </button>
    </div>
  );
}
